/* ---------- real service logos (served by aqeelOS from /ui/logo, cached on the box) ---------- */
const baseDomain=h=>{const p=String(h||'').toLowerCase().split('.').filter(Boolean);if(p.length<=2)return p.join('.');const sld=p[p.length-2];return (['co','com','org','net','ac','gov'].includes(sld)&&p[p.length-1].length===2?p.slice(-3):p.slice(-2)).join('.')};
const hostOf=u=>{try{return new URL(u).hostname}catch{return ''}};
const CH_DOMAINS={telegram:'telegram.org',discord:'discord.com',whatsapp:'whatsapp.com',slack:'slack.com',signal:'signal.org',sms:'twilio.com',matrix:'matrix.org',mattermost:'mattermost.com',bluebubbles:'bluebubbles.app',dingtalk:'dingtalk.com',feishu:'feishu.cn',wecom:'qq.com',wechat:'wechat.com',qqbot:'qq.com',yuanbao:'tencent.com',google_chat:'chat.google.com',weixin:'wechat.com',wecom_callback:'work.weixin.qq.com',line:'line.me',teams:'teams.microsoft.com',msgraph_webhook:'microsoft.com',ntfy:'ntfy.sh',simplex:'simplex.chat',whatsapp_cloud:'whatsapp.com',irc:'libera.chat'};
const logoImg=(domain,letter,bg)=>domain?`<span class="logo img"><img src="/ui/logo?d=${encodeURIComponent(domain)}&v=3" alt="" loading="lazy" decoding="async"></span>`:`<span class="logo" style="background:${bg||'var(--ink)'}${bg?'':';color:var(--surface)'}">${esc(letter)}</span>`;
const mcpDomain=m=>{const h=hostOf(m.url)||hostOf(m.source)||hostOf(m.install_url);return h&&!/github\.com|npmjs|localhost/.test(h)?baseDomain(h):(m.name?String(m.name).toLowerCase().replace(/[^a-z0-9-]/g,'')+'.com':'')};

