 // delivery choices belong to the agent it runs on
 d.querySelector('#whAgent').onchange=async e=>{const t=(await H('/cron/delivery-targets?profile='+encodeURIComponent(e.target.value)).catch(()=>({targets:[]}))).targets||[];d.querySelector('#whDel').innerHTML='<option value="">Reply to the caller</option>'+t.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')};
