PAGES.pairing=async(p,el)=>{
 const me=(agentProfile()||'default');let links=[];try{links=(await UI('/ui/channels/links?agent='+encodeURIComponent(me))).links||[]}catch{}
 const lists=await Promise.all([{prof:me,label:''},...links.map(l=>({prof:l.name,label:linkTitle(l)}))].map(async x=>({...x,d:await H('/pairing?profile='+encodeURIComponent(x.prof)).catch(()=>({pending:[],approved:[],err:true}))})));
 const tag=(u)=>u.__label?' · '+esc(u.__label):'',bad=lists.filter(x=>x.d.err).map(x=>x.label||ident(x.prof).name);
 const d={pending:lists.flatMap(x=>(x.d.pending||[]).map(u=>({...u,__prof:x.prof,__label:x.label}))),approved:lists.flatMap(x=>(x.d.approved||[]).map(u=>({...u,__prof:x.prof,__label:x.label})))};
 const who=u=>`${logoImg(CH_DOMAINS[u.platform],(u.platform||'?')[0].toUpperCase(),CH_COLORS[u.platform])}<div class="txt"><b>${esc(u.user_name||u.user_id)} · ${esc(pretty(u.platform))}${tag(u)}</b><span>${u.request_id?'Code '+esc(u.request_id)+' · ':''}${u.age_minutes!=null?Math.round(u.age_minutes)+' min ago':'ID '+esc(u.user_id)}</span></div>`;
 Pages._pairProfs=[...new Set(d.pending.map(u=>u.__prof))];setActions(d.pending.length?`<button class="ghost" data-act="pair-clear">Decline all waiting</button>`:'');
 el.innerHTML=`${bad.length?`<p class="err-line">Couldn’t load requests for ${esc(bad.join(', '))}. <button data-act="reload">Try again</button></p>`:''}<div class="panel card"><h2>People waiting</h2><p class="sub">Someone messaged one of ${esc(ident(me).name)}’s channels and needs your OK before the agent answers them.</p>${(d.pending||[]).map(u=>`<div class="row" style="padding:12px 12px;margin:0 -12px;border:0"><div class="main-c">${who(u)}</div><div class="act"><button class="primary" data-act="pair-ok" data-p="${esc(u.platform)}" data-r="${esc(u.request_id)}" data-prof="${esc(u.__prof)}">Approve</button></div></div>`).join('')||'<p class="hint" style="margin:0">Nobody is waiting.</p>'}</div>
 <div class="panel card"><h2>Approved</h2><p class="sub">These people can message ${esc(ident(me).name)}.</p>${(d.approved||[]).map(u=>`<div class="row" style="padding:12px 12px;margin:0 -12px;border:0"><div class="main-c">${who(u)}</div><div class="act"><button class="ghost" data-act="pair-revoke" data-p="${esc(u.platform)}" data-u="${esc(u.user_id)}" data-prof="${esc(u.__prof)}">Remove access</button></div></div>`).join('')||'<p class="hint" style="margin:0">No one yet. Approve requests above once your channels are connected.</p>'}</div>`;
};
ACT['pair-ok']=async a=>{try{await post(H,'/pairing/approve?profile='+encodeURIComponent(a.dataset.prof||S.profile||'default'),{platform:a.dataset.p,request_id:a.dataset.r,profile:a.dataset.prof||S.profile||undefined});toast('Approved');reload()}catch(e){fail(e)}};
ACT['pair-revoke']=async a=>{if(!await confirmBox('Remove access?','They can no longer message your agents.','Remove access'))return;try{await post(H,'/pairing/revoke?profile='+encodeURIComponent(a.dataset.prof||S.profile||'default'),{platform:a.dataset.p,user_id:a.dataset.u,profile:a.dataset.prof||S.profile||undefined});toast('Access removed');reload()}catch(e){fail(e)}};
// clears every agent and linked connection whose requests are on screen, not only the selected agent's
ACT['pair-clear']=async()=>{try{let n=0;for(const pr of Pages._pairProfs?.length?Pages._pairProfs:[agentProfile()||'default'])n+=(await post(H,'/pairing/clear-pending?profile='+encodeURIComponent(pr))).cleared||0;toast('Cleared '+plural(n,'request'));reload()}catch(e){fail(e)}};

/* ===================== Abilities › Skills ===================== */
Pages.skillsCache=async()=>Pages._skills||(Pages._skills=await H('/skills').catch(()=>[]));
PAGES.skills=async(p,el)=>{
 const tab=S.tab.skills||'Installed';
 setActions(`<button data-act="sk-update">${icon('refresh',16)}Update all</button><button class="primary" data-act="sk-new">${icon('plus',16)}New skill</button>`);
 if(tab==='Tool groups')return toolsetsView(el);
 if(tab==='Find more skills')return hubView(el);
 const skills=await H('/skills');Pages._skills=skills;const cats=[...new Set(skills.map(s=>s.category||'other'))].sort();const cat=S.skillCat||'All';const q=(S.skillQ||'').toLowerCase();
 const list=skills.filter(s=>(cat==='All'||s.category===cat)&&(!q||(s.name+' '+s.description).toLowerCase().includes(q)));
 el.innerHTML=`${tabs('skills',['Installed','Tool groups','Find more skills'])}<div class="toolbar"><div class="search">${icon('search',16)}<input id="skQ" placeholder="Search ${skills.length} skills" value="${esc(S.skillQ||'')}"></div><select id="skCat" style="width:auto"><option>All</option>${cats.map(c=>`<option ${c===cat?'selected':''} value="${esc(c)}">${esc(pretty(c))}</option>`).join('')}</select><span class="chip">${skills.filter(s=>s.enabled).length} on</span></div>
 <div class="card list">${list.map((s,i)=>`<div class="row clickable" ${st(i)} data-act="sk-open" data-name="${esc(s.name)}"><div class="main-c"><span class="ic ${s.enabled?'blue':''}">${icon('sparkle',17)}</span><div class="txt"><b>${esc(s.name)}</b><span>${esc(s.description)} · ${esc(pretty(s.category))}${s.provenance&&s.provenance!=='bundled'?' · '+esc(s.provenance):''}</span></div></div><div class="act">${toggle(s.enabled,s.name,'data-act="sk-toggle" data-name="'+esc(s.name)+'"')}</div></div>`).join('')||'<div class="state-box">No skills match.</div>'}</div>`;
 placePills();let t;$('#skQ').oninput=e=>{clearTimeout(t);t=setTimeout(()=>{if(!el.isConnected||route().page?.id!=='skills')return;S.skillQ=e.target.value;PAGES.skills(p,el).then(()=>{const i=$('#skQ');if(!i)return;i.focus();i.setSelectionRange(i.value.length,i.value.length)})},200)};$('#skCat').onchange=e=>{S.skillCat=e.target.value;PAGES.skills(p,el)};
};
ACT['sk-toggle']=async a=>{try{await put(H,'/skills/toggle',{name:a.dataset.name,enabled:a.checked});toast((a.checked?'Enabled ':'Disabled ')+a.dataset.name+' · applies to new chats')}catch(e){a.checked=!a.checked;fail(e)}};
ACT['sk-open']=(a,e)=>{if(e.target.closest('.switch'))return;Pages.openSkill(a.dataset.name)};
ACT['sk-new']=()=>Pages.openSkill(null);
ACT['sk-update']=()=>runAction('Update skills','/skills/hub/update',{});
Pages.openSkill=async name=>{let content='',cat='';if(name){try{const c=await H('/skills/content?name='+encodeURIComponent(name));content=c.content}catch(e){return fail(e)}}
 const sk=(Pages._skills||[]).find(s=>s.name===name);
 const d=drawer(name||'New skill',`${name?`<div style="display:flex;gap:8px;margin-bottom:14px;flex-wrap:wrap"><span class="chip">${esc(pretty(sk?.category))}</span>${sk?chipState(sk.enabled,'Enabled','Off'):''}${sk?.provenance?`<span class="chip">${esc(sk.provenance)}</span>`:''}</div>`:`<label>Name</label><input id="skName" placeholder="site-report"><label>Category</label><input id="skCatIn" placeholder="productivity">`}<label>Instructions (SKILL.md)</label><textarea id="skBody" rows="18" style="font-family:var(--mono);font-size:12.5px;line-height:1.55">${esc(content||'---\nname: \ndescription: \n---\n\n# \n\nWhen to use this skill, then the steps.\n')}</textarea>${name&&sk?.provenance==='hub'?`<button class="ghost" style="margin-top:12px;color:var(--bad)" data-act="sk-uninstall" data-name="${esc(name)}">${icon('trash',15)}Uninstall from hub</button>`:''}`,`<button class="ghost" data-act="close">Cancel</button><button class="primary" id="skSave">${name?'Save changes':'Create skill'}</button>`);
 d.querySelector('#skSave').onclick=async()=>{const body=$('#skBody').value;try{if(name)await put(H,'/skills/content',{name,content:body});else{const n=$('#skName').value.trim();if(!n)return toast('Give it a name','err');await post(H,'/skills',{name:n,content:body,category:$('#skCatIn').value.trim()||undefined})}Pages._skills=null;closeLayers();toast(name?'Skill saved':'Skill created');if(route().page?.id==='skills')reload()}catch(e){fail(e)}}};
ACT['sk-uninstall']=async a=>{if(!await confirmBox('Uninstall this skill?','It is removed from the box.','Uninstall'))return;closeLayers();runAction('Uninstall '+a.dataset.name,'/skills/hub/uninstall',{name:a.dataset.name}).then(()=>{Pages._skills=null;reload()})};
async function toolsetsView(el){const ts=await H('/tools/toolsets');
 el.innerHTML=`${tabs('skills',['Installed','Tool groups','Find more skills'])}<div class="grid-cards">${ts.map((t,i)=>`<div class="card tile" ${st(i)} style="cursor:default"><div class="tile-top"><span class="logo" style="background:var(--soft);color:var(--ink-2)">${icon('layers',18)}</span><div><h3>${esc(t.label||t.name)}</h3><span style="font-size:12.5px;color:var(--muted)">${esc(t.platform_label||'')}</span></div></div><p>${esc(t.description||'')}</p><div class="tile-foot">${t.available&&t.configured?'<span class="chip ok"><i class="dot"></i>Ready</span>':'<span class="chip warn">Setup needed</span>'}${toggle(t.enabled,t.label||t.name,'data-act="ts-toggle" data-name="'+esc(t.name)+'"')}</div><button data-act="ts-setup" data-name="${esc(t.name)}" style="align-self:flex-start">${icon('sliders',15)}${t.configured?'Settings':'Set up'}</button></div>`).join('')}</div>`;placePills()}
ACT['ts-toggle']=async a=>{try{await put(H,'/tools/toolsets/'+encodeURIComponent(a.dataset.name),{enabled:a.checked});toast(a.dataset.name+(a.checked?' on':' off'))}catch(e){a.checked=!a.checked;fail(e)}};
ACT['ts-setup']=async a=>{const name=a.dataset.name;let cfg;try{cfg=await H('/tools/toolsets/'+encodeURIComponent(name)+'/config')}catch(e){return fail(e)}
 if(!Pages._agents?.length){try{Pages._agents=((await H('/profiles')).profiles||[]).map(x=>x.name)}catch{}}
 // the one in use first; plain titles ("Image generation", not "Image Gen setup")
 const provs=(cfg.providers||[]).filter(pv=>!pv.requires_nous_auth&&!/nous/i.test(pv.name)).sort((a,b)=>(b.is_active?1:0)-(a.is_active?1:0));
 const title=({image_gen:'Image generation',video_gen:'Video generation',tts:'Text to speech',web:'Web search',browser:'Browser',vision:'Image reading'})[name]||pretty(name);
 const now=provs.find(pv=>pv.is_active);const many=(Pages._agents||[]).length>1;
 const d=drawer(title,provs.length?`<p class="hint" style="margin:0 0 6px">${now?`Now: <b>${esc(now.name)}</b>. `:''}Choose who provides this ability for ${esc(ident((agentProfile()||'default')).name)}, then add its keys if it needs any.</p>${many?`<label class="capt" style="margin:8px 0 0"><input type="checkbox" id="tsAll" checked><span>Use the choice for all agents</span></label>`:''}${provs.map((pv,i)=>`<div class="panel card" style="box-shadow:none;padding:16px 18px;margin:12px 0 0;${pv.is_active?'border-color:var(--blue)':''}"><div style="display:flex;align-items:center;gap:10px;justify-content:space-between"><b style="font-size:14px">${esc(pv.name)}</b>${pv.badge?`<span class="chip">${esc(pv.badge)}</span>`:''}</div><p class="hint">${esc(pv.tag||'')}</p>${(pv.env_vars||[]).map(v=>`<label>${esc(v.prompt||v.key)}</label><input data-tenv="${i}" data-key="${esc(v.key)}" type="${/URL$/.test(v.key)?'text':'password'}" placeholder="${v.is_set?'Set · leave blank to keep':esc(v.default||'')}">${v.url?`<p class="hint"><a href="${esc(v.url)}" target="_blank" rel="noopener">Get a key</a></p>`:''}`).join('')}<div style="display:flex;gap:8px;margin-top:12px">${pv.is_active?'<span class="chip ok"><i class="dot"></i>In use</span>'+(pv.env_vars?.length?`<button data-act="ts-use" data-name="${esc(name)}" data-prov="${esc(pv.name)}" data-i="${i}" data-keys="1">Save keys</button>`:''):`<button data-act="ts-use" data-name="${esc(name)}" data-prov="${esc(pv.name)}" data-i="${i}">Use this</button>`}${pv.post_setup?`<button class="ghost" data-act="ts-post" data-name="${esc(name)}" data-key="${esc(pv.post_setup.key||pv.post_setup)}">Run setup step</button>`:''}</div>${pv.status&&pv.status!=='ready'?`<p class="hint">Status: ${esc(pretty(pv.status))}</p>`:''}</div>`).join('')}`:'<p class="hint">This toolset has no options to set.</p>');
 Pages._tsName=name;};
ACT['ts-use']=async a=>{const name=a.dataset.name,i=a.dataset.i;const env={};$$(`[data-tenv="${i}"]`).forEach(x=>{if(x.value.trim())env[x.dataset.key]=x.value.trim()});const all=$('#tsAll')?.checked;const agents=all?(Pages._agents||[(agentProfile()||'default')]):[(agentProfile()||'default')];
 try{for(const ag of agents){const q='?profile='+encodeURIComponent(ag);if(Object.keys(env).length)await put(H,'/tools/toolsets/'+encodeURIComponent(name)+'/env'+q,{env});await put(H,'/tools/toolsets/'+encodeURIComponent(name)+'/provider'+q,{provider:a.dataset.prov})}
  closeLayers();toast((a.dataset.keys?'Keys saved':a.dataset.prov+' now provides it')+(all&&agents.length>1?' for all '+agents.length+' agents':''));reload()}catch(e){fail(e)}};
ACT['ts-post']=a=>runAction('Setup step','/tools/toolsets/'+encodeURIComponent(a.dataset.name)+'/post-setup',{key:a.dataset.key});
async function hubView(el){el.innerHTML=`${tabs('skills',['Installed','Tool groups','Find more skills'])}<div class="toolbar"><div class="search" style="max-width:none">${icon('search',16)}<input id="hubQ" placeholder="Search the skill hub (e.g. seo, invoices, notion)" value="${esc(S.hubQ||'')}"></div></div><div id="hubRes">${S.hubQ?skeleton(3):'<div class="state-box">Search community and official skills, then install with one click.</div>'}</div>`;placePills();
 const run=async()=>{const q=$('#hubQ').value.trim();S.hubQ=q;if(!q)return;$('#hubRes').innerHTML=skeleton(3);try{const r=await H('/skills/hub/search'+qp({q,source:'all',limit:30}));const res=r.results||[];$('#hubRes').innerHTML=res.length?`<div class="card list">${res.map((s,i)=>`<div class="row" ${st(i)}><div class="main-c"><span class="ic">${icon('sparkle',17)}</span><div class="txt"><b>${esc(s.name)}</b><span>${esc(s.description||'')} · ${esc(s.source)}${s.trust_level?' · '+esc(s.trust_level):''}</span></div></div><div class="act">${r.installed?.[s.identifier]?'<span class="chip ok">Installed</span>':`<button data-act="hub-install" data-id="${esc(s.identifier)}">Install</button>`}</div></div>`).join('')}</div>`:'<div class="state-box">Nothing found.</div>'}catch(e){showError($('#hubRes'),e)}};
 $('#hubQ').onkeydown=e=>{if(e.key==='Enter')run()};if(S.hubQ)run()}
ACT['hub-install']=a=>runAction('Install skill','/skills/hub/install',{identifier:a.dataset.id}).then(()=>{Pages._skills=null});

/* ===================== Abilities › MCP ===================== */
PAGES.mcp=async(p,el)=>{
 const tab=S.tab.mcp||'Your servers';setActions(`<button class="primary" data-act="mcp-add">${icon('plus',16)}Add server</button>`);
 if(tab==='Catalog'){el.innerHTML=`${tabs('mcp',['Your servers','Catalog'])}<div class="grid-cards">${'<div class="card tile"><div class="skel" style="height:120px"></div></div>'.repeat(6)}</div>`;let c;try{c=await H('/mcp/catalog');if(!(c.entries||[]).length)throw new Error('The catalog came back empty.')}catch(e){el.innerHTML=`${tabs('mcp',['Your servers','Catalog'])}<div class="panel card"><h2>The catalog did not load</h2><p class="sub">${esc(e.message||'The engine did not answer.')} The engine may be busy or restarting.</p><button class="primary" data-act="reload">Try again</button></div>`;return}Pages._mcpCat=c.entries||[];el.innerHTML=`${tabs('mcp',['Your servers','Catalog'])}<div class="grid-cards">${(c.entries||[]).map((m,i)=>`<div class="card tile" ${st(i)} style="cursor:default"><div class="tile-top">${logoImg(mcpDomain(m),m.name[0].toUpperCase())}<div><h3>${esc(pretty(m.name))}</h3><span style="font-size:12.5px;color:var(--muted)">${esc(m.transport)}${m.auth_type?' · '+esc(m.auth_type):''}</span></div></div><p>${esc(m.description)}</p><div class="tile-foot">${m.installed?chipState(m.enabled,'Installed','Installed · off')+(m.url&&!(m.bootstrap||[]).length?`<button class="ghost small" data-act="mcp-install" data-copy="1" data-name="${esc(m.name)}" data-env="${esc((m.required_env||[]).map(v=>v.key||v).join(','))}">${icon('plus',14)}Add another</button>`:''):`<button data-act="mcp-install" data-name="${esc(m.name)}" data-env="${esc((m.required_env||[]).map(v=>v.key||v).join(','))}">Install</button>`}</div></div>`).join('')}</div>`;placePills();return}
 const d=await H('/mcp/servers');const list=d.servers||[];Pages._mcp=list;
 el.innerHTML=`${tabs('mcp',['Your servers','Catalog'])}${list.length?`<div class="card list">${list.map((m,i)=>`<div class="row" ${st(i)}><div class="main-c">${m.url?logoImg(baseDomain(hostOf(m.url)),m.name[0].toUpperCase()):`<span class="ic ${m.enabled!==false?'blue':''}">${icon('plug',17)}</span>`}<div class="txt"><b>${esc(m.name)}</b><span>${esc(m.url||[m.command,...(m.args||[])].join(' '))}${m.tool_count!=null?' · '+plural(m.tool_count,'tool'):''}${m.auth_required||m.needs_auth?' · needs sign-in':''}</span></div></div><div class="act">${m.auth_required||m.needs_auth||m.auth==='oauth'||(m.url&&!m.command)?`<button data-act="mcp-auth" data-name="${esc(m.name)}">Sign in</button>`:''}<button data-act="mcp-test" data-name="${esc(m.name)}">Test</button>${toggle(m.enabled!==false,m.name,'data-act="mcp-toggle" data-name="'+esc(m.name)+'"')}<button class="ghost icon" title="Duplicate" aria-label="Duplicate" data-act="mcp-dup" data-name="${esc(m.name)}">${icon('copy',16)}</button><button class="ghost icon" title="Remove" aria-label="Remove" data-act="mcp-del" data-name="${esc(m.name)}">${icon('trash',16)}</button></div></div>`).join('')}</div>`:emptyBox('No MCP servers yet','Add one by URL or command, or install from the catalog.',`<button data-tabset="mcp:Catalog">Open catalog</button>`)}`;placePills();
};
ACT['mcp-test']=async a=>{a.disabled=true;try{const r=await post(H,'/mcp/servers/'+encodeURIComponent(a.dataset.name)+'/test');const tools=r.tools||[];drawer('Test: '+a.dataset.name,r.ok===false?`<p class="err-line">${esc(r.error||'Could not connect')}</p>`:`<p style="margin:0 0 12px"><span class="chip ok"><i class="dot"></i>Connected</span> ${plural(tools.length,'tool')} found</p><div class="card list">${tools.map(t=>`<div class="row"><div class="txt"><b>${esc(t.name||t)}</b><span style="white-space:normal">${esc(t.description||'')}</span></div></div>`).join('')}</div>`)}catch(e){fail(e)}finally{a.disabled=false}};
ACT['mcp-toggle']=async a=>{try{await put(H,'/mcp/servers/'+encodeURIComponent(a.dataset.name)+'/enabled',{enabled:a.checked});toast(a.checked?'On · applies after the agents restart':'Off · applies after the agents restart')}catch(e){a.checked=!a.checked;fail(e)}};
ACT['mcp-del']=async a=>{if(!await confirmBox('Remove this server?',`aqeelOS stops using “${esc(a.dataset.name)}”.`,'Remove'))return;try{await del(H,'/mcp/servers/'+encodeURIComponent(a.dataset.name));toast('Removed');reload()}catch(e){fail(e)}};
ACT['mcp-auth']=async a=>{try{const f=await post(H,'/mcp/servers/'+encodeURIComponent(a.dataset.name)+'/auth');const id=f.flow_id||f.id;if(f.auth_url||f.url)window.open(f.auth_url||f.url,'_blank','noopener');const d=drawer('Sign in to '+a.dataset.name,`<p style="color:var(--ink-2);margin:0 0 12px">Finish signing in in the tab that opened, then come back.</p>${f.auth_url||f.url?`<p><a href="${esc(f.auth_url||f.url)}" target="_blank" rel="noopener">Open the sign-in page again</a></p>`:''}<p class="hint" id="mcpSt">Waiting…</p>`);for(let i=0;i<150&&d.isConnected&&id;i++){await sleep(2000);const s=await H('/mcp/oauth/flows/'+encodeURIComponent(id));d.querySelector('#mcpSt').textContent='Status: '+pretty(s.status||'waiting');if(/complete|success|done|approved/.test(s.status||'')){closeLayers();toast('Signed in');reload();return}if(/fail|error|expired/.test(s.status||''))return}}catch(e){fail(e)}};
ACT['mcp-add']=()=>{const d=drawer('Add MCP server',`${tabs('mcpKind',['URL','Command'],'URL')}<label>Name</label><input id="mName" placeholder="github"><div id="mUrlBox"><label>Server URL</label><input id="mUrl" placeholder="https://api.example.com/mcp"><label>Bearer token (optional)</label><input id="mTok" type="password"></div><div id="mCmdBox" hidden><label>Command</label><input id="mCmd" placeholder="npx"><label>Arguments</label><input id="mArgs" placeholder="-y @modelcontextprotocol/server-postgres postgres://…"><label>Environment (KEY=VALUE per line)</label><textarea id="mEnv" rows="3" style="font-family:var(--mono)"></textarea></div>`,`<button class="ghost" data-act="close">Cancel</button><button class="primary" id="mGo">Add server</button>`);placePills();
 d.querySelector('[data-tabs=mcpKind]').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(!b)return;const cmd=b.dataset.tab==='Command';$('#mUrlBox').hidden=cmd;$('#mCmdBox').hidden=!cmd});
 d.querySelector('#mGo').onclick=async()=>{const cmd=!$('#mCmdBox').hidden;const body={name:$('#mName').value.trim()};if(!body.name)return toast('Give it a name','err');if(cmd){body.command=$('#mCmd').value.trim();body.args=$('#mArgs').value.trim().split(/\s+/).filter(Boolean);body.env=Object.fromEntries($('#mEnv').value.split('\n').map(l=>l.split('=')).filter(x=>x[0]&&x.length>1).map(([k,...v])=>[k.trim(),v.join('=').trim()]))}else{body.url=$('#mUrl').value.trim();if($('#mTok').value)body.bearer_token=$('#mTok').value}
  try{await post(H,'/mcp/servers',body);closeLayers();toast('Server added · Test it to see its tools');reload()}catch(e){fail(e)}}};
ACT['mcp-install']=async a=>{const keys=(a.dataset.env||'').split(',').filter(Boolean);let env={};const copy=a.dataset.copy==='1';let as=a.dataset.name;
 // another copy of an app you already have: its own name (and keys), e.g. two Airtable workspaces
 if(copy){let have=[];try{have=((await H('/mcp/servers')).servers||[]).map(x=>x.name)}catch{}let n=2;while(have.includes(a.dataset.name+'-'+n))n++;as=a.dataset.name+'-'+n}
 if(keys.length||copy){const d=drawer((copy?'Another ':'Install ')+pretty(a.dataset.name),(copy?`<p class="hint" style="margin:0 0 8px">A second ${esc(pretty(a.dataset.name))} with its own name${keys.length?' and keys':''}, for example another account. Agents see both.</p><label>Name</label><input id="ciName" value="${esc(as)}" pattern="[a-z0-9][a-z0-9_-]*">`:'')+keys.map(k=>`<label>${esc(k)}</label><input type="password" data-k="${esc(k)}">`).join(''),`<button class="ghost" data-act="close">Cancel</button><button class="primary" id="ciGo">${copy?'Add':'Install'}</button>`);await new Promise(r=>d.querySelector('#ciGo').onclick=r);if(copy)as=(d.querySelector('#ciName').value||as).trim().toLowerCase().replace(/[^a-z0-9_-]+/g,'-');d.querySelectorAll('[data-k]').forEach(i=>env[i.dataset.k]=i.value);closeLayers()}
 // The engine's own catalog install stops to ask a question in its terminal (tool picker) that nobody can answer from the web,
 // so catalog tools with a plain address are added directly; anything else still goes through the engine.
 try{const e=(Pages._mcpCat||[]).find(x=>x.name===a.dataset.name);
  if(e&&e.url&&!(e.bootstrap||[]).length&&!e.needs_install){await post(H,'/mcp/servers',{name:as,url:e.url,env});toast(e.auth_type==='oauth'?pretty(as)+' added. Press Sign in on it to connect your account.':pretty(e.name)+' added. Ready to use.')}
  else{const r=await post(H,'/mcp/catalog/install',{name:a.dataset.name,env,enable:true});if(r.action)actionDrawer('Installing '+a.dataset.name,r.action);else toast(a.dataset.name+' installed')}
  S.tab.mcp='Your servers';reload()}catch(er){fail(er)}};

/* ===================== Abilities › Plugins ===================== */
PAGES.plugins=async(p,el)=>{
 const tab=S.tab.plugins||'Installed';setActions(`<button data-act="pl-rescan">${icon('refresh',16)}Rescan</button>`);
 if(tab==='Browse'){const c=await H('/dashboard/plugins/catalog');el.innerHTML=`${tabs('plugins',['Installed','Browse'])}<div class="grid-cards">${(c.entries||[]).map((x,i)=>`<div class="card tile" ${st(i)} style="cursor:default"><div class="tile-top"><span class="logo" style="background:var(--ink)">${esc(x.name[0].toUpperCase())}</span><div><h3>${esc(x.name)}</h3><span style="font-size:12.5px;color:var(--muted)">${esc((x.repo||'').replace('https://github.com/',''))}</span></div></div><p>${esc((x.description||'').slice(0,220))}${(x.description||'').length>220?'…':''}</p><div class="tile-foot"><span class="chip">Catalog</span><button data-act="pl-install" data-repo="${esc(x.repo)}" data-name="${esc(x.name)}" data-sha="${esc(x.sha||'')}">Install</button></div></div>`).join('')}</div>`;placePills();return}
 const h=await H('/dashboard/plugins/hub');const list=h.plugins||[];
 el.innerHTML=`${tabs('plugins',['Installed','Browse'])}<div class="card list">${list.map((x,i)=>{const on=x.runtime_status==='enabled';return `<div class="row" ${st(i)}><div class="main-c"><span class="ic ${on?'blue':''}">${icon('layers',17)}</span><div class="txt"><b>${esc(x.name)}</b><span>${esc(x.source)} · v${esc(x.version||'?')} · ${esc((x.description||'').slice(0,110))}</span></div></div><div class="act">${toggle(on,x.name,'data-act="pl-toggle" data-name="'+esc(x.name)+'"')}<button class="ghost icon" data-menu="plugin" data-name="${esc(x.name)}" data-remove="${x.can_remove?1:''}" data-update="${x.can_update_git?1:''}" data-dash="${x.has_dashboard_manifest?1:''}" data-hidden="${x.user_hidden?1:''}" aria-label="More">${icon('more',18)}</button></div></div>`}).join('')}</div>`;placePills();
};
ACT['pl-toggle']=async a=>{try{const r=await post(UI,'/ui/plugins/toggle',{agent:(agentProfile()||'default'),name:a.dataset.name,enabled:a.checked});   /* per agent, not always the main one */toast((a.checked?'Enabled':'Disabled')+(r.restart_required?' · restart the agents to apply':''))}catch(e){a.checked=!a.checked;fail(e)}};
ACT['pl-rescan']=async()=>{try{const r=await H('/dashboard/plugins/rescan');toast('Found '+plural(r.count||0,'plugin'));reload()}catch(e){fail(e)}};
ACT['pl-install']=async a=>{try{const r=await post(H,'/dashboard/agent-plugins/install',{repo:a.dataset.repo,name:a.dataset.name,sha:a.dataset.sha||undefined});if(r.action||r.name&&r.pid)actionDrawer('Installing '+a.dataset.name,r.action||r.name);else toast(a.dataset.name+' installed');S.tab.plugins='Installed'}catch(e){fail(e)}};
Pages.pluginMenu=el=>{const n=el.dataset.name;const base='/dashboard/agent-plugins/'+encodeURIComponent(n);
 const items=[el.dataset.update&&{label:'Update',icon:'refresh',run:async()=>{try{await post(H,base+'/update',{accept_capabilities:false});toast('Updated');reload()}catch(e){fail(e)}}},
  el.dataset.dash&&{label:el.dataset.hidden?'Show in menu':'Hide from menu',icon:'eye',run:async()=>{try{await post(H,'/dashboard/plugins/'+encodeURIComponent(n)+'/visibility',{hidden:!el.dataset.hidden});toast('Saved');reload()}catch(e){fail(e)}}},
  el.dataset.remove&&'-',el.dataset.remove&&{label:'Remove',icon:'trash',bad:true,run:async()=>{if(!await confirmBox('Remove plugin?',`“${esc(n)}” is deleted from the box.`,'Remove'))return;try{await del(H,base);toast('Removed');reload()}catch(e){fail(e)}}}].filter(Boolean);
 menu(el,items.length?items:[{label:'Bundled with aqeelOS · nothing to change',icon:'shield'}])};

