/* ===================== System › Usage ===================== */
// several agents' usage added together: per day and per model
function mergeUsage(all){const day=new Map(),mod=new Map();const add=(t,s)=>{for(const [k,v] of Object.entries(s))if(typeof v==='number')t[k]=(t[k]||0)+v};
 for(const u of all){for(const d of u.daily||[]){const t=day.get(d.day)||{day:d.day};add(t,d);day.set(d.day,t)}for(const m of u.by_model||[]){const t=mod.get(m.model)||{model:m.model};add(t,m);mod.set(m.model,t)}}
 return {daily:[...day.values()].sort((a,b)=>a.day<b.day?-1:1),by_model:[...mod.values()].sort((a,b)=>(b.estimated_cost||0)-(a.estimated_cost||0))}}
ACT['usage-pick']=async a=>{const list=await viewAgents();const who=S.usageAgent||'*';
 menu(a,[{header:'Whose usage'},{label:'All agents',icon:'layers',sub:'Every agent added together',on:who==='*',run:()=>{S.usageAgent='*';reload()}},'-',...list.map(n=>({label:ident(n).name,icon:'user',on:n===who,run:()=>{S.usageAgent=n;reload()}}))],{search:list.length>8,matchWidth:true})};
ACT['currency-pick']=a=>{const c=currency(),admin=S.me?.admin!==false,def=S.defaults?.currency||'USD';
 menu(a,[{header:'Show costs in'},{label:'US dollars',sub:'$',on:c==='USD',run:()=>setCurrency('USD')},{label:'Rupiah',sub:'Rp, at today’s rate',on:c==='IDR',run:()=>setCurrency('IDR')},...(admin&&c!==def?['-',{label:'Use '+(c==='IDR'?'rupiah':'US dollars')+' for everyone',icon:'user',sub:'For people who haven’t picked one',run:()=>ACT['currency-default']()}]:[])],{matchWidth:false})};
ACT['currency-default']=async()=>{try{await post(UI,'/ui/defaults',{currency:currency()});S.defaults={...(S.defaults||{}),currency:currency()};toast('Everyone who hasn’t picked a currency now sees '+(currency()==='IDR'?'rupiah':'US dollars'));reload()}catch(e){fail(e)}};
PAGES.usage=async(p,el)=>{
 const days={'7 days':7,'30 days':30,'90 days':90}[S.tab.usage||'7 days'];
 // dollars or rupiah: the tab sets the person's choice, which every cost in the app follows
 const list=await viewAgents().catch(()=>[]);const who=S.usageAgent&&(S.usageAgent==='*'||list.includes(S.usageAgent))?S.usageAgent:list.length>1?'*':(S.profile||'default');
 const cur=currency()==='IDR'?'Rp IDR':'$ USD',isDefault=currency()===(S.defaults?.currency||'USD');
 setActions('<div class="u-bar">'+(list.length>1?`<button class="u-pick" data-act="usage-pick" aria-haspopup="menu" title="Whose usage to show">${icon(who==='*'?'layers':'user',15)}<span>${who==='*'?'All agents':esc(ident(who).name)}</span>${icon('chevD',14)}</button>`:'')+`<button class="u-pick" data-act="currency-pick" aria-haspopup="menu" title="Currency for costs"><span>${cur}</span>${icon('chevD',14)}</button>`+tabs('usage',['7 days','30 days','90 days'])+'</div>');placePills();
 const bad=[],one=a=>H('/analytics/usage?days='+days+'&profile='+encodeURIComponent(a)).catch(()=>{bad.push(ident(a).name);return{daily:[],by_model:[]}});
 const u=who==='*'?mergeUsage(await Promise.all((list.length?list:['default']).map(one))):await one(who);const daily=u.daily||[];
 const sum=k=>daily.reduce((a,d)=>a+(d[k]||0),0);const inp=sum('input_tokens'),out=sum('output_tokens'),cache=sum('cache_read_tokens'),cost=sum('estimated_cost'),actual=sum('actual_cost'),ses=sum('sessions');
 const hit=inp+cache?Math.round(cache/(inp+cache)*100):0;
 const series=Array.from({length:days},(_,i)=>{const d=new Date(Date.now()-(days-1-i)*864e5).toISOString().slice(0,10);const r=daily.find(x=>x.day===d)||{};return {d,i:(r.input_tokens||0)+(r.cache_read_tokens||0),o:r.output_tokens||0,c:r.estimated_cost||0}});
 const max=Math.max(1,...series.map(s=>s.i+s.o));
 el.innerHTML=`${bad.length?`<p class="err-line" style="margin:0 0 12px">Usage for ${esc(bad.join(', '))} couldn’t be loaded, so these totals are incomplete. <button data-act="reload">Try again</button></p>`:''}<div class="stats">${[['Tokens',num(inp+out+cache),`in ${num(inp)} · cached ${num(cache)} · out ${num(out)}`],['Cache hit',hit+'%','of input read from cache'],['Est. cost',money(cost,{cents:true}),actual?'actual $'+actual.toFixed(2):'list price; plans may cost $0'],['Sessions',num(ses),(ses/days).toFixed(1)+' a day']].map(([a,b,c],i)=>`<div class="card stat" ${st(i)}><span class="th">${a}</span><b>${b}</b><small>${esc(c)}</small></div>`).join('')}</div>
 <div class="panel card"><div style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap"><h2>Tokens per day</h2><div class="legend"><span><i style="background:var(--blue)"></i>Input + cache</span><span><i style="background:var(--sky-1)"></i>Output</span></div></div><div class="chart">${series.map((s,k)=>`<div class="b" title="${s.d}: ${num(s.i)} in · ${num(s.o)} out · ${money(s.c,{cents:true})}"><i class="in" style="height:${s.i/max*100}%;animation-delay:${k*12}ms"></i><i class="out" style="height:${Math.max(s.o?1:0,s.o/max*100)}%;animation-delay:${k*12+40}ms"></i></div>`).join('')}</div><div class="chart-x"><span>${series[0].d.slice(5)}</span><span>${series[Math.floor(days/2)].d.slice(5)}</span><span>${series[days-1].d.slice(5)}</span></div></div>
 <div class="stack-2"><div class="panel card"><h2>By model</h2><div class="tbl"><table><thead><tr><th class="th">Model</th><th class="th num">Sessions</th><th class="th num">Tokens</th><th class="th num">Est. cost</th></tr></thead><tbody>${(u.by_model||[]).map(m=>`<tr><td>${esc(modelLabel(m.model))}</td><td class="num">${m.sessions}</td><td class="num">${num((m.input_tokens||0)+(m.output_tokens||0))}</td><td class="num">${money(m.estimated_cost||0,{cents:true})}</td></tr>`).join('')||'<tr><td colspan="4" style="color:var(--muted)">No usage yet</td></tr>'}</tbody></table></div></div>
 <div class="panel card"><h2>By day</h2><div class="tbl"><table><thead><tr><th class="th">Day</th><th class="th num">Sessions</th><th class="th num">Input</th><th class="th num">Output</th><th class="th num">Cost</th></tr></thead><tbody>${daily.slice().reverse().map(d=>`<tr><td>${esc(d.day)}</td><td class="num">${d.sessions}</td><td class="num">${num(d.input_tokens)}</td><td class="num">${num(d.output_tokens)}</td><td class="num">${money(d.estimated_cost||0,{cents:true})}</td></tr>`).join('')||'<tr><td colspan="5" style="color:var(--muted)">No usage yet</td></tr>'}</tbody></table></div></div></div>`;
};

