 const box=$('#logBox');const load=async()=>{try{const d=await H('/logs'+qp({file:o.file,lines:o.lines,level:o.level==='ALL'?'':o.level,component:o.component==='all'?'':o.component}));const atEnd=box.scrollHeight-box.scrollTop-box.clientHeight<40;box.innerHTML=(d.lines||[]).map(l=>{const e=esc(l.replace(/\n$/,''));return / (ERROR|CRITICAL) /.test(l)?`<span class="e">${e}</span>`:/ WARNING /.test(l)?`<span class="w">${e}</span>`:/ DEBUG /.test(l)?`<span class="d">${e}</span>`:e}).join('\n')||'(no lines)';if(atEnd)box.scrollTop=box.scrollHeight}catch(e){box.textContent=e.message}};
 await load();box.scrollTop=box.scrollHeight;
