/* ===================== System › Settings ===================== */
const CFG_WORDS=[['hermes-cli','aqeelos-cli'],['hermes gateway','aqeelos gateway'],['Hermes','aqeelOS']];
const cfgShow=v=>{if(v==null)return v;const t=typeof v==='string'?v:JSON.stringify(v);if(!/hermes/i.test(t))return v;let o=t;for(const [a,b] of CFG_WORDS)o=o.split(a).join(b);try{return typeof v==='string'?o:JSON.parse(o)}catch{return v}};
const cfgSave=v=>{if(typeof v!=='string')return v;let o=v;for(const [a,b] of CFG_WORDS.slice(0,2))o=o.split(b).join(a);return o};
PAGES.settings=async(p,el)=>{
 setActions(`<button data-act="cfg-raw">Raw YAML</button><button data-act="cfg-import">${icon('upload',16)}Import</button><button data-act="cfg-export">${icon('download',16)}Export</button><button class="primary" data-act="cfg-save">Save</button>`);
 // searching, switching groups and Load defaults redraw from the unsaved copy instead of fetching it again
 const reuse=Pages._cfgReuse&&Pages._cfg;Pages._cfgReuse=false;
 const [cfg,schema,consent]=await Promise.all([reuse?Pages._cfg:H('/config'),H('/config/schema'),null]);if(!reuse){Pages._cfgChanged=false;Pages._loadedDefaults=false}Pages._cfg=cfg;Pages._dirty={};
 const get=k=>cfgShow(k.split('.').reduce((o,x)=>o==null?undefined:o[x],cfg));
 const fields=Object.entries(schema.fields||{});const catOf=f=>f.category||'general';const allCats=[...new Set(fields.map(f=>catOf(f[1])))];const order=schema.category_order||[];
 // the engine's order first, then any group it left out, A to Z
 const cats=[...order.filter(c=>allCats.includes(c)),...allCats.filter(c=>!order.includes(c)).sort()];
 const q=(S.cfgQ||'').toLowerCase();const cur=cats.includes(S.cfgCat)?S.cfgCat:cats[0];
 const ctl=(k,f)=>{const v=get(k);const opts=f.options||f.choices||f.enum;
  if(f.type==='boolean'||typeof v==='boolean')return toggle(!!v,k,`data-cfg="${esc(k)}" data-t="bool"`);
  if(opts&&opts.length)return `<select data-cfg="${esc(k)}">${opts.map(o=>`<option ${String(o)===String(v)?'selected':''}>${esc(o)}</option>`).join('')}</select>`;
  if(f.type==='text')return `<textarea data-cfg="${esc(k)}" data-t="str" rows="4">${esc(v??'')}</textarea>`;
  if(cfgNestable(v))return cfgNest(k,v);
  if((f.type==='list'||Array.isArray(v))&&(v==null||Array.isArray(v)&&v.every(x=>x==null||typeof x!=='object'))){const a=v||[];return `<input data-cfg="${esc(k)}" data-t="csv" ${a.length&&a.every(x=>typeof x==='number')?'data-n="1"':''} placeholder="Values, separated by commas" value="${esc(a.join(', '))}">`}
  if(f.type==='list'||Array.isArray(v)||(v&&typeof v==='object'))return `<textarea data-cfg="${esc(k)}" data-t="json" rows="${Array.isArray(v)&&v.length<4?2:4}" style="font-family:var(--mono);font-size:12px">${esc(JSON.stringify(v??(f.type==='list'?[]:{}),null,1))}</textarea>`;
  const n=f.type==='number'||typeof v==='number';return `<input data-cfg="${esc(k)}" data-t="${n?'num':'str'}" ${n?'type="number" step="any" inputmode="decimal"':''} value="${esc(v??'')}">`};
 const hit=([k,f])=>(k+' '+k.split('.').pop().replace(/_/g,' ')+' '+catOf(f)+' '+pretty(catOf(f))+' '+(f.description||'')).toLowerCase().includes(q);
 const shown=q?cats.flatMap(c=>fields.filter(x=>catOf(x[1])===c&&hit(x))):fields.filter(([k,f])=>catOf(f)===cur);
 Pages._cfgShown=shown.map(x=>x[0]);Pages._cfgScope=q?'Search results':pretty(cur);
 // a heading where the search results move to another group, or where a group's keys move to another section
 let lastS='';const rows=shown.map(([k,f])=>{const sec=q?catOf(f):k.includes('.')?k.split('.')[0]:'';const head=sec&&sec!==lastS&&(q||sec!==cur)?`<div class="cfg-sec">${esc(pretty(sec))}</div>`:'';lastS=sec;const c=ctl(k,f);const row=fieldRow(esc(pretty(k.split('.').pop())),`${f.description?esc(f.description):''}<span class="cfg-key">${esc(k)}</span>`,c);return head+(/cfg-nest|<textarea/.test(c)?row.replace('class="field"','class="field wide"'):row)}).join('');
 el.innerHTML=`<div class="toolbar"><div class="search" style="max-width:none">${icon('search',16)}<input id="cfQ" placeholder="Search ${fields.length} settings" value="${esc(S.cfgQ||'')}">${S.cfgQ?`<button class="ghost icon search-x" data-act="cfg-clearq" title="Clear search" aria-label="Clear search">${icon('x',15)}</button>`:''}</div></div><div class="two wide-main"><div class="panel card"><h2>${q?'Search results':esc(pretty(cur))}</h2><p class="sub">${plural(shown.length,'setting')} · changes apply to new chats, or after the agents restart</p>${rows||'<p class="hint">Nothing matches.</p>'}</div>
 <div style="align-self:start;display:grid;gap:16px"><div class="panel card" style="margin:0"><h2>Groups</h2><p class="sub">Jump to a section</p>${cats.map(c=>`<button class="item ${c===cur&&!q?'on':''}" data-act="cfg-cat" data-c="${esc(c)}">${esc(pretty(c))}<span class="n">${fields.filter(f=>catOf(f[1])===c).length}</span></button>`).join('')}</div>
 <div class="panel card" style="margin:0"><h2>Reset</h2><p class="sub">${q?'Put the settings found by this search back to their defaults':'Put the settings in this group back to their defaults'}. Nothing else changes, and you still need to Save.</p><button data-act="cfg-defaults" ${shown.length?'':'disabled'}>${q?'Reset these results':'Reset this group'}</button></div></div></div>`;placePills();
 el.addEventListener('input',e=>{const i=e.target.closest('[data-cfg]');if(i)Pages._dirty[i.dataset.cfg]=i});el.addEventListener('change',e=>{const i=e.target.closest('[data-cfg]');if(i)Pages._dirty[i.dataset.cfg]=i});
 let t;$('#cfQ').oninput=e=>{clearTimeout(t);t=setTimeout(()=>{try{cfgApply()}catch(er){return cfgFail(er)}Pages._cfgReuse=true;S.cfgQ=e.target.value;PAGES.settings(p,el).then(()=>{const i=$('#cfQ');i.focus();i.setSelectionRange(i.value.length,i.value.length)})},250)};
 
};
// folds the edited fields into the unsaved copy of the settings
function cfgApply(){const c=Pages._cfg,dirty=Object.entries(Pages._dirty||{});for(const [k,i] of dirty){const t=i.dataset.t;let v;if(t==='bool')v=i.checked;else if(t==='num'){v=i.value.trim()===''?0:Number(i.value);if(Number.isNaN(v))throw new Error('“'+pretty(k.split('.').pop())+'” needs a number')}else if(t==='csv'){v=i.value.split(',').map(x=>cfgSave(x.trim())).filter(Boolean);if(i.dataset.n&&v.every(x=>!Number.isNaN(Number(x))))v=v.map(Number)}else v=t==='json'?JSON.parse(cfgSave(i.value)||'null'):cfgSave(i.value);const parts=k.split('.');let o=c;parts.slice(0,-1).forEach(x=>o=o[x]??(o[x]={}));o[parts.at(-1)]=v;delete Pages._dirty[k]}if(dirty.length)Pages._cfgChanged=true}
// objects and lists of objects get one labelled box per value (keys with dots in them stay as JSON, their path would be ambiguous)
const cfgDots=v=>v!=null&&typeof v==='object'&&Object.entries(v).some(([s,x])=>s.includes('.')||cfgDots(x));
const cfgNestable=v=>!cfgDots(v)&&(v!=null&&typeof v==='object'&&!Array.isArray(v)&&Object.keys(v).length>0||Array.isArray(v)&&v.some(x=>x!=null&&typeof x==='object'&&!Array.isArray(x)));
const cfgNest=(p,v)=>{if(Array.isArray(v))return `<div class="cfg-nest">${v.map((x,i)=>`<div class="cfg-leaf"><small>Item ${i+1}</small>${cfgNest(p+'.'+i,x)}</div>`).join('')}</div>`;if(v!=null&&typeof v==='object')return `<div class="cfg-nest">${Object.entries(v).map(([s,x])=>`<div class="cfg-leaf"><small>${esc(pretty(s))}</small>${cfgNest(p+'.'+s,x)}</div>`).join('')||'<small class="hint">Empty</small>'}</div>`;
 if(typeof v==='boolean')return `<div>${toggle(v,p,`data-cfg="${esc(p)}" data-t="bool"`)}</div>`;const n=typeof v==='number';return `<input data-cfg="${esc(p)}" data-t="${n?'num':'str'}" ${n?'type="number" step="any" inputmode="decimal"':''} value="${esc(v??'')}">`};
const cfgFail=e=>fail(e.name==='SyntaxError'?new Error('One of the list or object fields is not valid JSON'):e);
ACT['cfg-cat']=a=>{try{cfgApply()}catch(e){return cfgFail(e)}Pages._cfgReuse=true;S.cfgCat=a.dataset.c;S.cfgQ='';reload()};
ACT['cfg-clearq']=()=>{try{cfgApply()}catch(e){return cfgFail(e)}Pages._cfgReuse=true;S.cfgQ='';reload()};
ACT['cfg-save']=async()=>{const c=Pages._cfg;try{cfgApply();if(!Pages._cfgChanged&&!Pages._loadedDefaults)return toast('Nothing changed');await put(H,'/config',{config:c});Pages._dirty={};Pages._cfgChanged=false;Pages._loadedDefaults=false;toast('Settings saved · new chats use them')}catch(e){cfgFail(e)}};
// on one agent's Settings page the form is the source, unsaved edits included; on All agents it is the agent you chat with
const cfgHere=()=>route().page?.id==='settings'&&!showingAll()&&Pages._cfg;
ACT['cfg-export']=async()=>{try{let c;if(cfgHere()){cfgApply();c=Pages._cfg}else c=await H('/config');downloadBlob(new Blob([JSON.stringify(c,null,2)],{type:'application/json'}),'aqeelos-config.json')}catch(e){cfgFail(e)}};
ACT['cfg-import']=()=>pickFile('.json',async f=>{let c;try{c=JSON.parse(await f.text())}catch{return toast('That file is not valid JSON','err')}if(!c||typeof c!=='object'||Array.isArray(c))return toast('That file does not hold settings','err');
 if(cfgHere()){Pages._cfg=c;Pages._dirty={};Pages._cfgChanged=true;Pages._cfgReuse=true;reload();return toast('Imported · check the values, then press Save to keep them')}
 if(!await confirmBox('Replace '+ident(agentProfile()||'default').name+'’s settings?','Every setting of the agent you chat with is replaced with the file’s values. To check them before saving, open that agent’s Settings and import there.','Replace'))return;try{await put(H,'/config',{config:c});toast('Settings imported');reload()}catch(e){fail(e)}});
ACT['cfg-defaults']=async()=>{const ks=Pages._cfgShown||[];if(!ks.length)return toast('Nothing to reset here');try{cfgApply()}catch(e){return cfgFail(e)}
 if(!await confirmBox('Reset '+plural(ks.length,'setting')+'?',(Pages._cfgScope||'This group')+': '+(ks.length===1?'it goes':'they go')+' back to the default. Every other setting stays as it is, and nothing is saved until you press Save.','Reset'))return;
 try{const dft=await H('/config/defaults');for(const k of ks){const parts=k.split('.');const v=parts.reduce((o,x)=>o==null?undefined:o[x],dft);let o=Pages._cfg;parts.slice(0,-1).forEach(x=>o=o[x]!=null&&typeof o[x]==='object'?o[x]:(o[x]={}));if(v===undefined)delete o[parts.at(-1)];else o[parts.at(-1)]=structuredClone(v)}Pages._cfgChanged=true;Pages._cfgReuse=true;reload();toast(plural(ks.length,'setting')+' reset · press Save to keep the change')}catch(e){fail(e)}};
ACT['cfg-raw']=async()=>{try{const r=await H('/config/raw');const d=drawer('config.yaml',`<p class="hint" style="margin:0 0 8px">${esc(r.path||'')}</p><textarea id="rawY" rows="28" style="font-family:var(--mono);font-size:12px;line-height:1.5">${esc(r.yaml)}</textarea>`,`<button class="ghost" data-act="close">Cancel</button><button class="primary" id="rawGo">Save YAML</button>`);d.style.width='min(720px,100vw)';d.querySelector('#rawGo').onclick=async()=>{try{await put(H,'/config/raw',{yaml_text:$('#rawY').value});closeLayers();toast('config.yaml saved');reload()}catch(e){fail(e)}}}catch(e){fail(e)}};

/* ===================== System › Host ===================== */
PAGES.host=async(p,el)=>{
 setActions(`<button class="primary" data-act="upd-check">${icon('refresh',16)}Check for updates</button>`);
 const [s,cur,hooks,ck,portal,pool,plan,box]=await Promise.all([H('/system/stats'),H('/curator').catch(()=>null),H('/ops/hooks').catch(()=>({hooks:[]})),H('/ops/checkpoints').catch(()=>null),null,H('/credentials/pool').catch(()=>({providers:[]})),H('/gateway/migrate/plan').catch(()=>null),UI('/ui/box').catch(()=>null)]);
 const bm=box?.memory?.limit?box.memory:null;
 const up=s.uptime_seconds||0;
 el.innerHTML=`<div class="stats">${[['CPU',s.cpu_count+' cores',`${s.cpu_percent??'—'}% · load ${(s.load_avg||[]).map(x=>x.toFixed(1)).join(' ')}`],bm?['Memory',bytes(bm.used)+' / '+bytes(bm.limit),`AI box · ${bm.pct}% used · whole server ${Math.round((s.memory?.used||0)/(s.memory?.total||1)*100)}%`]:['Memory',bytes(s.memory?.used)+' / '+bytes(s.memory?.total),bytes(s.memory?.available)+' free'],['Disk',bytes(s.disk?.used)+' / '+bytes(s.disk?.total),bytes(s.disk?.free)+' free'],['Uptime',up>86400?Math.floor(up/86400)+' days':Math.floor(up/3600)+' h',esc(s.os+' '+s.os_release)]].map(([a,b,c],i)=>`<div class="card stat" ${st(i)}><span class="th">${a}</span><b style="font-size:22px">${b}</b><small>${c}</small></div>`).join('')}</div>
 ${bm&&box.parts?.length?`<div class="panel card mem-parts"><h2>What uses memory</h2><p class="sub">The AI box has ${bytes(bm.limit)} of its own. Near the limit, the system stops the biggest program (often the browser or a reply in progress).${bm.oom_kills?` It has done that ${bm.oom_kills} time${bm.oom_kills>1?'s':''}.`:''}</p>
  ${box.parts.map(x=>`<div class="mem-row"><span>${esc(x.name)}</span><i style="--w:${Math.max(2,Math.round(x.bytes/bm.limit*100))}%"></i><b>${bytes(x.bytes)}</b></div>`).join('')}</div>`:''}
 <div id="updBox"></div>
 <div class="two"><div>
  <div class="panel card"><h2>Start and stop agents</h2><p class="sub">What runs every agent: chats, channels and schedules.</p><div style="display:flex;gap:8px;flex-wrap:wrap"><button data-act="gw-restart">${icon('refresh',16)}Restart</button><button data-act="gw-start">${icon('play',16)}Start</button><button data-act="gw-stop">${icon('pause',16)}Stop</button></div>${plan&&plan.eligible?`<p class="hint" style="margin-top:12px">aqeelOS suggests running every agent from one engine. <button class="ghost" data-act="gw-migrate">Migrate…</button></p>`:''}</div>
  <div class="panel card"><h2>Background helpers</h2><p class="sub">Skill curator, checkpoints and shell hooks.</p>
   ${cur?fieldRow('Skill curator',`Tidies skills aqeelOS made itself · every ${cur.interval_hours} h${cur.last_run_at?' · last '+when(cur.last_run_at):''}`,`<div style="display:flex;gap:8px;align-items:center">${toggle(!cur.paused,'Curator','data-act="cur-toggle"')}<button data-act="cur-run">Run now</button></div>`):''}
   ${ck?fieldRow('Checkpoints',`Rollback store · ${bytes(ck.total_bytes)} in ${plural((ck.sessions||[]).length,'session')}`,`<button data-act="ck-prune">Prune</button>`):''}
   ${fieldRow('Shell hooks',plural((hooks.hooks||[]).length,'hook')+' · run commands on events',`<button data-act="hooks-open">Manage</button>`)}</div>
  <div class="panel card"><h2>Credential pool</h2><p class="sub">Extra API keys aqeelOS rotates through, per provider.</p>${(pool.providers||[]).map(pv=>`<div class="row" style="padding:10px 12px;margin:0 -12px;border-top:1px solid var(--border)"><div class="txt"><b>${esc(pv.provider||pv.name)}</b><span>${plural((pv.entries||pv.keys||[]).length,'key')}</span></div><div class="act">${(pv.entries||pv.keys||[]).map((k,i)=>`<span class="chip" style="font-family:var(--mono)">${esc(k.label||k.redacted||k.preview||'key')}<button class="ghost icon" style="width:18px;min-height:18px" data-act="pool-del" data-p="${esc(pv.provider||pv.name)}" data-i="${i}" aria-label="Remove">${icon('x',11)}</button></span>`).join('')}</div></div>`).join('')||'<p class="hint" style="margin:0 0 10px">None yet.</p>'}<button data-act="pool-add">${icon('plus',15)}Add key</button></div>
 </div><div>
  <div class="panel card"><h2>Maintenance</h2><p class="sub">Each runs in the background with a live log.</p><div style="display:flex;gap:8px;flex-wrap:wrap">${[['Check for problems','/ops/doctor'],['Security check','/ops/security-audit'],['Back up','/ops/backup'],['Update skills','/skills/hub/update'],['Instruction size','/ops/prompt-size'],['Download support file','/ops/dump'],['Update settings format','/ops/config-migrate']].map(([l,u])=>`<button data-act="op" data-u="${u}" data-l="${esc(l)}">${l}</button>`).join('')}<button data-act="op-restore">Restore…</button></div></div>
  <div class="panel card"><h2>About this box</h2><p class="sub">${esc(s.hostname)} · ${esc(s.arch)} · Python ${esc(s.python_version)} · aqeelOS engine ${esc(s.hermes_version)}</p></div>
 </div></div>`;
};
ACT['upd-check']=async()=>{const b=$('#updBox');b.innerHTML='<div class="skel" style="height:64px;margin-bottom:16px"></div>';try{const r=await H('/hermes/update/check?force=true');b.innerHTML=`<div class="panel card" style="display:flex;align-items:center;gap:16px;justify-content:space-between;flex-wrap:wrap"><div><h2>${r.update_available?'Update available':'Up to date'}</h2><p class="sub" style="margin:0">${esc(r.message||'')} · ${esc(r.current_version)}${r.behind>0?' · '+plural(r.behind,'commit')+' behind':''}</p></div>${r.update_available?(r.can_apply?`<button class="primary" data-act="upd-go" data-n="${r.behind}">Update now</button>`:`<code>${esc(r.update_command)}</code>`):''}</div>`}catch(e){showError(b,e)}};
ACT['upd-go']=async a=>{if(!await confirmBox('Update the aqeelOS engine?',`Pulls ${plural(+a.dataset.n||0,'commit')} and restarts aqeelOS. Chats in progress may be interrupted.`,'Update',false))return;runAction('Updating aqeelOS','/hermes/update')};
ACT['gw-start']=()=>restartGateway();   // the proper start (its own session, full environment), not the dashboard's
ACT['gw-stop']=async()=>{if(!await confirmBox('Stop the agents?','Channels, schedules and this chat stop working until you start it again.','Stop'))return;runAction('Stopping the agents','/gateway/stop?profile=default')};
ACT['gw-migrate']=async()=>{if(!await confirmBox('Run every agent from one engine?','All agents will run from one engine.','Migrate',false))return;runAction('Moving agents','/gateway/migrate')};
ACT['cur-toggle']=async a=>{try{await put(H,'/curator/paused',{paused:!a.checked});toast(a.checked?'Curator on':'Curator paused')}catch(e){a.checked=!a.checked;fail(e)}};
ACT['cur-run']=()=>runAction('Skill curator','/curator/run');
ACT['ck-prune']=()=>runAction('Pruning checkpoints','/ops/checkpoints/prune');
ACT['op']=a=>runAction(a.dataset.l,a.dataset.u,a.dataset.u==='/ops/backup'?{}:undefined).then(r=>{if(r?.archive)toast('Backup saved: '+r.archive)});

ACT['op-restore']=()=>pickFile('.zip,.tar,.gz,.tgz',async f=>{if(!await confirmBox('Restore from this backup?','Current aqeelOS data on the box is replaced by '+esc(f.name)+'.','Restore'))return;const fd=new FormData();fd.append('force','false');fd.append('file',f,f.name);try{const r=await H('/ops/import-upload',{method:'POST',body:fd});if(r.name)actionDrawer('Restoring',r.name)}catch(e){fail(e)}});
ACT['pool-add']=async()=>{const d=drawer('Add pooled key',`<label>Provider</label><input id="plP" placeholder="openrouter"><label>API key</label><input id="plK" type="password"><label>Label (optional)</label><input id="plL" placeholder="work account">`,`<button class="ghost" data-act="close">Cancel</button><button class="primary" id="plGo">Add</button>`);d.querySelector('#plGo').onclick=async()=>{try{await post(H,'/credentials/pool',{provider:$('#plP').value.trim(),api_key:$('#plK').value.trim(),label:$('#plL').value.trim()||undefined});closeLayers();toast('Key added');reload()}catch(e){fail(e)}}};
ACT['pool-del']=async a=>{if(!await confirmBox('Remove this key?','It is taken out of the rotation.','Remove'))return;try{await del(H,'/credentials/pool/'+encodeURIComponent(a.dataset.p)+'/'+a.dataset.i);toast('Removed');reload()}catch(e){fail(e)}};
ACT['hooks-open']=async()=>{const h=await H('/ops/hooks');const d=drawer('Shell hooks',`<div class="approval" style="margin-top:0"><h4>${icon('alert',16)}Hooks run commands on the box</h4><p>Only add commands you trust. A hook does nothing until you grant consent.</p></div>${(h.hooks||[]).map(x=>`<div class="row" style="padding:10px 12px;margin:0 -12px;border-top:1px solid var(--border)"><div class="txt"><b style="font-family:var(--mono);font-size:13px">${esc(x.event)}</b><span style="white-space:normal;font-family:var(--mono)">${esc(x.command)}${x.approved===false?' · no consent':''}</span></div><div class="act"><button class="ghost icon" data-act="hook-del" data-e="${esc(x.event)}" data-c="${esc(x.command)}" aria-label="Remove">${icon('trash',16)}</button></div></div>`).join('')||'<p class="hint">No hooks yet.</p>'}<h3 style="font-size:15px;margin:22px 0 4px">New hook</h3><label>Event</label><select id="hkE">${(h.valid_events||[]).map(e=>`<option>${esc(e)}</option>`).join('')}</select><label>Command</label><input id="hkC" style="font-family:var(--mono)" placeholder="/home/claude/hooks/notify.sh"><label>Matcher (optional)</label><input id="hkM" placeholder="terminal"><label>Timeout (seconds)</label><input id="hkT" type="number" value="30"><label style="display:flex;align-items:center;justify-content:space-between">I trust this command (grant consent) ${toggle(false,'Consent','id="hkA"')}</label>`,`<button class="ghost" data-act="close">Close</button><button class="primary" id="hkGo">Add hook</button>`);d.querySelector('#hkGo').onclick=async()=>{try{await post(H,'/ops/hooks',{event:$('#hkE').value,command:$('#hkC').value.trim(),matcher:$('#hkM').value.trim()||undefined,timeout:+$('#hkT').value||undefined,approve:$('#hkA').checked});toast('Hook added. Restarting the agents so it takes effect…');post(UI,'/ui/gateway/restart').catch(()=>{});ACT['hooks-open']()}catch(e){fail(e)}}};
ACT['hook-del']=async a=>{try{await del(H,'/ops/hooks',{event:a.dataset.e,command:a.dataset.c});toast('Hook removed. Restarting the agents…');post(UI,'/ui/gateway/restart').catch(()=>{});ACT['hooks-open']()}catch(e){fail(e)}};

/* ===================== Agent identity (name, title, picture, description, personality) ===================== */
ACT['ident-open']=(a,e)=>{if(e.target.closest('[data-menu]'))return;identityDrawer(a.dataset.name)};
// The first sentence of SOUL.md is the agent's self-introduction; we rewrite only that.
const soulIntro=(name,title)=>`You are ${name}${title?', '+title:''}, the AI agent inside aqeelOS. Always call yourself ${name}. Never claim to be another assistant or say another company made you; if someone asks what model powers you, name the model you are running on.`;
function withIntro(soul,name,title){const s=String(soul||'');const intro=soulIntro(name,title);
 if(/^You are [^\n]*?(Nous Research|aqeelOS)[^\n]*?\./.test(s))return s.replace(/^You are [^\n]*?(?:built by Nous Research\.|Claude\.|aqeelOS\.)(?: Always call yourself[^.]*\.)?(?: Never (?:say|claim)[^.]*\.)?(?:[^.]*(?:run on Claude|running on)\.)?/,intro);
 return intro+(s?' '+s:'')}
async function identityDrawer(name){
 const prof=(Pages._profiles||[]).find(p=>p.name===name)||{name};const id=ident(name);let soul='';
 try{soul=(await H('/profiles/'+encodeURIComponent(name)+'/soul')).content||''}catch{}
 let newPic=null,removePic=false;
 const d=drawer('Edit identity',`<div class="ident-top"><div class="ident-ava" id="idAva">${id.avatar?`<img src="${esc(id.avatar)}" alt="">`:esc(id.name[0].toUpperCase())}</div><div style="display:flex;gap:8px;flex-wrap:wrap"><button type="button" id="idPick">${icon('upload',15)}Upload picture</button><button type="button" class="ghost" id="idDrop" ${id.avatar?'':'hidden'}>Remove</button></div><p class="hint" style="margin:6px 0 0">PNG, JPG or WebP · square works best · under 2 MB</p></div>
  <label>Name</label><input id="idName" maxlength="60" value="${esc(id.name)}" placeholder="aqeelOS">
  <label>Title</label><input id="idTitle" maxlength="80" value="${esc(id.title)}" placeholder="Operations assistant">
  <label>Description</label><input id="idDesc" value="${esc(prof.description||'')}" placeholder="What this agent is for">
  <label style="display:flex;align-items:center;justify-content:space-between;gap:12px">Update how it introduces itself ${toggle(true,'Update introduction','id="idIntro"')}</label><p class="hint">Rewrites the first line of its personality so it always calls itself by this name.</p>
  <label>Personality (SOUL)</label><textarea id="idSoul" rows="12" style="font-size:13px;line-height:1.55">${esc(soul)}</textarea>
  <p class="hint">Profile folder: <code>${esc(name)}</code> (the internal name stays the same)</p>`,
  `<button class="ghost" data-act="close">Cancel</button><button class="primary" id="idSave">Save identity</button>`);
 const ava=d.querySelector('#idAva'),soulBox=d.querySelector('#idSoul'),intro=d.querySelector('#idIntro');
 const preview=()=>{if(intro.checked)soulBox.value=withIntro(soulBox.dataset.base??soulBox.value,d.querySelector('#idName').value.trim()||'aqeelOS',d.querySelector('#idTitle').value.trim())};
 soulBox.dataset.base=soul;soulBox.oninput=()=>{soulBox.dataset.base=soulBox.value};preview();
 d.querySelector('#idName').oninput=preview;d.querySelector('#idTitle').oninput=preview;intro.onchange=()=>{if(!intro.checked)soulBox.value=soulBox.dataset.base;else preview()};
 d.querySelector('#idPick').onclick=()=>pickFile('image/png,image/jpeg,image/webp,image/gif',f=>{if(f.size>2e6)return toast('Pictures must be under 2 MB','err');newPic=f;removePic=false;ava.innerHTML=`<img src="${URL.createObjectURL(f)}" alt="">`;d.querySelector('#idDrop').hidden=false});
 d.querySelector('#idDrop').onclick=()=>{newPic=null;removePic=true;ava.textContent=(d.querySelector('#idName').value||'a')[0].toUpperCase();d.querySelector('#idDrop').hidden=true};
 d.querySelector('#idSave').onclick=async()=>{const nm=d.querySelector('#idName').value.trim();if(!nm)return toast('Give it a name','err');const btn=d.querySelector('#idSave');btn.disabled=true;
  try{const base='/ui/'+'identities/'+encodeURIComponent(name);
   await call('',base,{method:'PUT',body:{name:nm,title:d.querySelector('#idTitle').value.trim()}});
   if(newPic){const r=await fetch('/ui/avatar/'+encodeURIComponent(name),{method:'PUT',headers:{'x-hui':'1','content-type':newPic.type},body:newPic});if(!r.ok)throw new Error((await r.json().catch(()=>({}))).error||'Picture upload failed')}
   if(removePic)await call('','/ui/avatar/'+encodeURIComponent(name),{method:'DELETE'});
   const desc=d.querySelector('#idDesc').value.trim();if(desc!==(prof.description||''))await put(H,'/profiles/'+encodeURIComponent(name)+'/description',{description:desc});
   if(soulBox.value!==soul)await put(H,'/profiles/'+encodeURIComponent(name)+'/soul',{content:soulBox.value});
   await loadIdentities();closeLayers();toast(nm+' saved · new chats use the new personality');paintSide();if(route().page?.id==='profiles')reload();document.title='aqeelOS'}
  catch(e){fail(e);btn.disabled=false}};
}

ACT['key-add']=()=>{const d=drawer('Add a key',`<label>Name</label><input id="kaN" placeholder="ADSPOWER_API_KEY" style="font-family:var(--mono)" autocomplete="off"><p class="hint">Capital letters, digits and underscores, e.g. ADSPOWER_API_KEY.</p><label>Value</label><input id="kaV" type="password" autocomplete="off"><p class="hint">Stored on the AI box only and never shown in full again.</p>`,`<button class="ghost" data-act="close">Cancel</button><button class="primary" id="kaGo">Save key</button>`);
 d.querySelector('#kaGo').onclick=async()=>{const k=$('#kaN').value.trim().toUpperCase(),v=$('#kaV').value.trim();if(!/^[A-Z][A-Z0-9_]{1,63}$/.test(k))return toast('Use a name like ADSPOWER_API_KEY','err');if(!v)return toast('Paste the value','err');try{await put(H,'/env',{key:k,value:v});closeLayers();toast(k+' saved');reload()}catch(e){fail(e)}}};

/* ===================== Models › Accounts (helpers; the page is in accounts-page.js) ===================== */
const UI=(path,o)=>call('',path,o);
const pctBar=(label,w)=>{if(!w)return '';const c=w.used>=90?'bad':w.used>=70?'warn':'ok';return `<div class="ubar"><div class="ubar-top"><span>${esc(label)}</span><b>${w.used}% used</b></div><div class="ubar-track"><i class="${c}" style="width:${Math.min(100,w.used)}%"></i></div><small>${w.resets?'Resets '+when(w.resets):''}</small></div>`};
// PAGES.accounts lives in accounts-page.js
ACT['acct-refresh']=()=>{Pages._acctFresh=true;reload()};
ACT['acct-add']=async()=>{const label=await promptBox('Add a Claude account','A name for this account (e.g. Work Max)','','Continue');if(!label)return;
 let st;try{st=await UI('/ui/accounts',{method:'POST',body:{label}})}catch(e){return fail(e)}
 if(!st.url)return toast('Claude did not start a sign-in. Try again.','err');
 const d=drawer('Sign in: '+label,`<ol style="padding-left:18px;line-height:1.8;color:var(--ink-2);margin:0 0 12px"><li><a href="${esc(st.url)}" target="_blank" rel="noopener">Open the Claude sign-in page</a>. Use the account you want to add. If Claude emails you a link, open it in the same browser.</li><li>Approve, then copy the code it shows (use its Copy button).</li><li>Paste it here.</li></ol><label>Code</label><input id="acCode" autocomplete="off"><p class="hint" id="acHint"></p>`,`<button class="ghost" id="acCancel">Cancel</button><button class="primary" id="acGo">Finish sign-in</button>`);
 window.open(st.url,'_blank','noopener');
 d.querySelector('#acCancel').onclick=async()=>{await UI('/ui/accounts/'+st.id+'/cancel',{method:'POST'}).catch(()=>{});closeLayers()};
 d.querySelector('#acGo').onclick=async()=>{const b=d.querySelector('#acGo');b.disabled=true;d.querySelector('#acHint').textContent='Checking…';try{const r=await UI('/ui/accounts/'+st.id+'/code',{method:'POST',body:{code:$('#acCode').value}});d.querySelector('#acHint').textContent=r.hint||'';if(r.state==='done'){closeLayers();toast(label+' added');Pages._acctFresh=true;reload()}else{b.disabled=false;if(r.state==='running'&&!d._watch)d._watch=watch()}}catch(e){fail(e);b.disabled=false}};
 // a slow sign-in can finish after the code wait: look for the new account while this window stays open
 const watch=()=>setTimeout(async function tick(){if(!d.isConnected)return;const l=await UI('/ui/accounts').catch(()=>null);if(!d.isConnected)return;if((l?.accounts||[]).some(x=>x.id===st.id)){closeLayers();toast(label+' added');Pages._acctFresh=true;reload()}else setTimeout(tick,4000)},4000);
};
Pages.acctMenu=el=>{const id=el.dataset.id;const a=(Pages._acct?.accounts||[]).find(x=>x.id===id)||{};
 menu(el,[{label:'Rename',icon:'edit',run:async()=>{const v=await promptBox('Rename account','Name',a.label);if(!v)return;try{await UI('/ui/accounts/'+id,{method:'PATCH',body:{label:v}});reload()}catch(e){fail(e)}}},
  ...(Object.keys(Pages._acct?.assign||{}).map(n=>({label:'Use for '+ident(n).name,icon:'user',on:Pages._acct.assign[n]===id,run:async()=>{try{await UI('/ui/accounts/assign',{method:'POST',body:{profile:n,account:id}});toast(ident(n).name+' now uses '+a.label);reload()}catch(e){fail(e)}}}))),
  id!=='main'&&'-',id!=='main'&&{label:'Remove account',icon:'trash',bad:true,run:async()=>{if(!await confirmBox('Remove '+esc(a.label)+'?','It is signed out and removed from the box. Agents must use another account first.','Remove'))return;try{await UI('/ui/accounts/'+id,{method:'DELETE'});toast('Removed');reload()}catch(e){fail(e)}}}])};
